def completar_tecnicas_base(apps, schema_editor):
    """Completa los seis provisionales conservando sus seguimientos pendientes."""
    alias = schema_editor.connection.alias
    TecnicaQA = apps.get_model('tecnicas', 'TecnicaQA')
    Paso = apps.get_model('tecnicas', 'Paso')
    Seguimiento = apps.get_model('tecnicas', 'SeguimientoTecnica')
    SeguimientoPaso = apps.get_model('tecnicas', 'SeguimientoPaso')
    Evidencia = apps.get_model('tecnicas', 'Evidencia')

    for datos in TECNICAS:
        tecnicas = TecnicaQA.objects.using(alias).filter(
            catalogo__nombre='Catálogo base',
            nombre='Técnica por definir · ' + datos['original'],
            descripcion__startswith='[PENDIENTE]',
        )
        for tecnica in tecnicas:
            pasos = Paso.objects.using(alias).filter(tecnica=tecnica)
            tiene_trabajo = (
                SeguimientoPaso.objects.using(alias).filter(
                    paso__in=pasos, completado=True
                ).exists()
                or Evidencia.objects.using(alias).filter(
                    seguimiento_paso__paso__in=pasos
                ).exists()
                or pasos.exclude(
                    instruccion__startswith='[PENDIENTE]'
                ).exists()
                or pasos.exclude(
                    evidencia_esperada__startswith='[PENDIENTE]'
                ).exists()
                or pasos.exclude(orden=1).exists()
            )
            if tiene_trabajo:
                raise RuntimeError(
                    'La técnica provisional con ID '
                    f'{tecnica.pk} tiene trabajo o contenido propio. '
                    'Revisa su historial antes de aplicar HU-12.'
                )

            for campo in (
                'nombre', 'descripcion', 'objetivo', 'pregunta_clave',
                'dimension', 'tipo_control',
            ):
                setattr(tecnica, campo, datos[campo])
            tecnica.save(using=alias)
            for orden, (instruccion, evidencia) in enumerate(datos['pasos'], 1):
                Paso.objects.using(alias).update_or_create(
                    tecnica=tecnica, orden=orden,
                    defaults={
                        'instruccion': instruccion,
                        'evidencia_esperada': evidencia,
                    },
                )
            for seguimiento in Seguimiento.objects.using(alias).filter(
                tecnica=tecnica
            ):
                for paso in pasos:
                    SeguimientoPaso.objects.using(alias).get_or_create(
                        seguimiento=seguimiento, paso=paso
                    )
                registrados = SeguimientoPaso.objects.using(alias).filter(
                    seguimiento=seguimiento
                )
                total = registrados.count()
                completos = registrados.filter(completado=True).count()
                seguimiento.porcentaje_avance = round(completos / total * 100, 2)
                seguimiento.save(using=alias, update_fields=['porcentaje_avance'])


